import { parseAbi } from "viem";
import type { AbiSource } from "./abi-sources.js";

const HEADER =
  "// Generated by scripts/make-abis.ts from scripts/abi-sources.ts. Do not edit by hand:\n" +
  "// change the signatures there and run `pnpm --filter @help-wanted/shared abis`.\n";

/** The text of `src/abi/<name>.ts`. */
export function renderAbiFile(source: AbiSource): string {
  const abi = parseAbi(source.signatures as readonly string[]);
  return `${HEADER}\n/** ${source.comment} */\nexport const ${source.name}Abi = ${JSON.stringify(abi, null, 2)} as const;\n`;
}

/**
 * The text of `src/abi/index.ts`: the protocol's ABIs written from signatures, then our own
 * contracts' ABIs, which `gen-abis.ts` writes from the compiler's output into `generated/`.
 */
export function renderIndexFile(sources: readonly AbiSource[]): string {
  const lines = sources.map((s) => `export { ${s.name}Abi } from "./${s.name}.js";`);
  return `${HEADER}\n${lines.join("\n")}\n\n// HELP WANTED's own contracts, from the launch projects' build output (\`abi:gen\`).\nexport * from "./generated/index.js";\n`;
}
